package org.apache.commons.math.ode.nonstiff;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.ode.ExpandableStatefulODE;
import org.apache.commons.math.ode.FirstOrderDifferentialEquations;
import org.apache.commons.math.ode.nonstiff.EmbeddedRungeKuttaIntegrator;
import org.apache.commons.math.ode.nonstiff.ExpandableStatefulODE;
import org.apache.commons.math.ode.nonstiff.RungeKuttaStepInterpolator;
import org.apache.commons.math.util.FastMath;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.mockito.Mockito.*;

/**
 * Unit tests for EmbeddedRungeKuttaIntegrator.integrate.
 */
public class EmbeddedRungeKuttaIntegrator_integrate_TriageGen1Test {

    private TestIntegrator integrator;

    @Mock
    private ExpandableStatefulODE mockEquations;

    @Mock
    private RungeKuttaStepInterpolator mockInterpolator;

    // Concrete implementation of the abstract class for testing purposes
    private static class TestIntegrator extends EmbeddedRungeKuttaIntegrator {
        private double errorToReturn = 0.5;
        private int computeDerivativesCalls = 0;

        protected TestIntegrator() {
            super("TestIntegrator", 
                  true, // fsal = true
                  new double[]{0.5, 1.0}, // c
                  new double[][]{{0.0, 0.0}, {0.5, 0.0}}, // a (simplified)
                  new double[]{0.5, 1.0}, // b
                  null, // prototype (will be mocked via prototype.copy)
                  1.0e-8, 1.0, 1.0e-6, 1.0e-6);
        }

        @Override
        public int getOrder() {
            return 2;
        }

        @Override
        protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) {
            return errorToReturn;
        }

        @Override
        protected void computeDerivatives(double t, double[] y, double[] yDot) {
            computeDerivativesCalls++;
            for (int i = 0; i < y.length; i++) {
                yDot[i] = 1.0; // Constant derivative for simplicity
            }
        }

        @Override
        protected double initializeStep(double t, double[] y, double[] yDot, double[] yTmp, double[] yDotK1) {
            return 0.1;
        }

        @Override
        protected double filterStep(double h, boolean forward, boolean isLast) {
            return h;
        }

        @Override
        protected double acceptStep(RungeKuttaStepInterpolator interpolator, double[] y, double[] yDot, double t) {
            return t; // for testing, assume we reached target immediately
        }

        // Mocking the prototype.copy() behavior via a trick or by overriding if possible.
        // Since prototype is final/protected, we use a spy or a subclass that handles it.
        @Override
        public void setEquations(ExpandableStatefulODE equations) {
            super.setEquations(equations);
        }
    }

    // Subclass to bypass the prototype.copy() issue in the real code
    private static class MockIntegrator extends TestIntegrator {
        private final RungeKuttaStepInterpolator interpolator;

        public MockIntegrator(RungeKuttaStepInterpolator interpolator) {
            this.interpolator = interpolator;
        }

        // We can't easily override the prototype.copy() in the source because it's called on 'prototype'
        // In a real test environment, we'd ensure the prototype is a mock that returns our mockInterpolator
    }

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);

        // Setup default mock behaviors
        when(mockEquations.getCompleteState()).thenReturn(new double[]{0.0});
        when(mockEquations.getTime()).thenReturn(0.0);
        when(mockEquations.getPrimaryMapper()).thenReturn(null);
        when(mockEquations.getSecondaryMappers()).thenReturn(null);

        // We need to provide a real-ish integrator instance
        // To handle the 'prototype.copy()' line, we create a custom implementation
        integrator = new TestIntegrator() {
            @Override
            public void integrate(final ExpandableStatefulODE equations, final double t) throws MathIllegalStateException, MathIllegalArgumentException {
                // We override the whole method to control the prototype.copy() behavior for testing
                // or we use a subclass that has a mock prototype.
                super.integrate(equations, t);
            }
        };

        // Since we cannot easily change the 'prototype' field if it's private, 
        // we rely on the fact that we are testing the logic. 
        // For this test to run without NullPointerException on prototype.copy(), 
        // we would ideally use Reflection to set the prototype field.
        java.lang.reflect.Field prototypeField = EmbeddedRungeKuttaIntegrator.class.getDeclaredField("prototype");
        prototypeField.setAccessible(true);
        RungeKuttaStepInterpolator mockProto = mock(RungeKuttaStepInterpolator.class);
        when(mockProto.copy()).thenReturn(mockInterpolator);
        prototypeField.set(integrator, mockProto);
    }

    @Test
    public void testIntegrateSuccess() throws Exception {
        when(mockEquations.getTime()).thenReturn(0.0);
        when(mockEquations.getCompleteState()).thenReturn(new double[]{0.0});

        integrator.errorToReturn = 0.5; // error < 1.0 (accept step)

        integrator.integrate(mockEquations, 0.1);

        verify(mockEquations).setTime(anyDouble());
        verify(mockEquations).setCompleteState(any(double[].class));
    }

    @Test
    public void testIntegrateWithStepRejection() throws Exception {
        when(mockEquations.getTime()).thenReturn(0.0);
        when(mockEquations.getCompleteState()).thenReturn(new double[]{0.0});

        // Force error >= 1.0 first, then < 1.0 to exit loop
        integrator.errorToReturn = 1.5; 

        // We need to simulate the loop progression. 
        // This is tricky with the provided code structure because error is updated inside the loop.
        // We'll use a custom error provider.
        TestIntegrator errorControllingIntegrator = new TestIntegrator() {
            private int count = 0;
            @Override
            protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) {
                count++;
                return (count <= 1) ? 1.5 : 0.5;
            }
            @Override
            protected double acceptStep(RungeKuttaStepInterpolator interpolator, double[] y, double[] yDot, double t) {
                return t; 
            }
        };

        // Setup prototype for the new integrator
        java.lang.reflect.Field prototypeField = EmbeddedRungeKuttaIntegrator.class.getDeclaredField("prototype");
        prototypeField.setAccessible(true);
        RungeKuttaStepInterpolator mockProto = mock(RungeKuttaStepInterpolator.class);
        when(mockProto.copy()).thenReturn(mockInterpolator);
        prototypeField.set(errorControllingIntegrator, mockProto);

        errorControllingIntegrator.integrate(mockEquations, 0.1);

        verify(mockEquations).setCompleteState(any(double[].class));
    }

    @Test
    public void testIntegrateBackward() throws Exception {
        when(mockEquations.getTime()).thenReturn(1.0);
        when(mockEquations.getCompleteState()).thenReturn(new double[]{1.0});

        // t < equations.getTime()
        integrator.integrate(mockEquations, 0.5);

        verify(mockEquations).setTime(anyDouble());
    }

    @Test
    public void testIntegrateWithVectorTolerance() throws Exception {
        // Accessing protected fields via reflection to set vector tolerances
        java.lang.reflect.Field vecAbsTol = EmbeddedRungeKuttaIntegrator.class.getDeclaredField("vecAbsoluteTolerance");
        vecAbsTol.setAccessible(true);
        vecAbsTol.set(integrator, new double[]{1e-6, 1e-6});

        java.lang.reflect.Field vecRelTol = EmbeddedRungeKuttaIntegrator.class.getDeclaredField("vecRelativeTolerance");
        vecRelTol.setAccessible(true);
        vecRelTol.set(integrator, new double[]{1e-6, 1e-6});

        when(mockEquations.getTime()).thenReturn(0.0);
        when(mockEquations.getCompleteState()).thenReturn(new double[]{0.0, 0.0});

        integrator.integrate(mockEquations, 0.1);

        verify(mockEquations).setCompleteState(any(double[].class));
    }

    @Test
    public void testSanityChecks() {
        // Testing that it throws exception if equations is null or something similar
        // (Assuming sanityChecks performs such checks)
        assertThrows(MathIllegalArgumentException.class, () -> {
            integrator.integrate(null, 0.1);
        });
    }
}
